{"path":"script.js","content":"const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

canvas.width = 800;
canvas.height = 600;

const TILE_SIZE = 40;
const GRID_WIDTH = canvas.width / TILE_SIZE;
const GRID_HEIGHT = canvas.height / TILE_SIZE;

// Game State
let towers = [];
let enemies = [];
let projectiles = [];
let path = []; // Array of {x, y} objects representing the path

// Pathfinding (simplified for now, a straight line)
function generatePath() {
    path = [];
    for (let i = 0; i < GRID_WIDTH; i++) {
        path.push({ x: i * TILE_SIZE, y: Math.floor(GRID_HEIGHT / 2) * TILE_SIZE });
    }
}

class Tower {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = TILE_SIZE;
        this.height = TILE_SIZE;
        this.range = 100;
        this.attackSpeed = 60; // frames between attacks
        this.attackTimer = 0;
        this.cost = 100;
    }

    draw() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x, this.y, this.width, this.height);
        ctx.strokeStyle = 'cyan';
        ctx.strokeRect(this.x, this.y, this.width, this.height);
    }

    update() {
        this.attackTimer++;
        if (this.attackTimer >= this.attackSpeed) {
            // Find target
            let target = this.findTarget();
            if (target) {
                projectiles.push(new Projectile(this.x + this.width / 2, this.y + this.height / 2, target));
                this.attackTimer = 0;
            }
        }
    }

    findTarget() {
        for (let i = 0; i < enemies.length; i++) {
            let enemy = enemies[i];
            const dist = Math.hypot(this.x - enemy.x, this.y - enemy.y);
            if (dist < this.range) {
                return enemy;
            }
        }
        return null;
    }
}

class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = TILE_SIZE * 0.7;
        this.height = TILE_SIZE * 0.7;
        this.speed = 1;
        this.health = 100;
        this.maxHealth = 100;
        this.pathIndex = 0;
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, this.width, this.height);
        // Health bar
        ctx.fillStyle = 'green';
        ctx.fillRect(this.x, this.y - 10, this.width * (this.health / this.maxHealth), 5);
    }

    update() {
        if (this.pathIndex < path.length) {
            let targetWaypoint = path[this.pathIndex];
            let dx = targetWaypoint.x - this.x;
            let dy = targetWaypoint.y - this.y;
            let dist = Math.hypot(dx, dy);

            if (dist < this.speed) {
                this.x = targetWaypoint.x;
                this.y = targetWaypoint.y;
                this.pathIndex++;
            } else {
                this.x += (dx / dist) * this.speed;
                this.y += (dy / dist) * this.speed;
            }
        } else {
            // Enemy reached end of path
            // Handle game over or health reduction
        }
    }
}

class Projectile {
    constructor(x, y, target) {
        this.x = x;
        this.y = y;
        this.radius = 5;
        this.speed = 5;
        this.target = target;
        this.damage = 20;
    }

    draw() {
        ctx.fillStyle = 'yellow';
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fill();
    }

    update() {
        if (this.target && this.target.health > 0) {
            let dx = this.target.x - this.x;
            let dy = this.target.y - this.y;
            let dist = Math.hypot(dx, dy);

            if (dist < this.speed) {
                this.target.health -= this.damage;
                return true; // Projectile hit
            } else {
                this.x += (dx / dist) * this.speed;
                this.y += (dy / dist) * this.speed;
            }
        }
        return false; // Projectile missed or target is dead
    }
}

// Event Listeners
canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    // Place tower
    const gridX = Math.floor(x / TILE_SIZE) * TILE_SIZE;
    const gridY = Math.floor(y / TILE_SIZE) * TILE_SIZE;

    // Check if a tower already exists at this position or if it's on the path
    const onPath = path.some(p => p.x === gridX && p.y === gridY);
    const towerExists = towers.some(t => t.x === gridX && t.y === gridY);

    if (!onPath && !towerExists) {
        towers.push(new Tower(gridX, gridY));
    }
});

// Game Loop
function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw path
    ctx.strokeStyle = 'gray';
    ctx.lineWidth = TILE_SIZE * 0.8;
    ctx.beginPath();
    if (path.length > 0) {
        ctx.moveTo(path[0].x + TILE_SIZE / 2, path[0].y + TILE_SIZE / 2);
        for (let i = 1; i < path.length; i++) {
            ctx.lineTo(path[i].x + TILE_SIZE / 2, path[i].y + TILE_SIZE / 2);
        }
    }
    ctx.stroke();

    // Update and draw towers
    towers.forEach(tower => {
        tower.update();
        tower.draw();
    });

    // Update and draw enemies
    for (let i = 0; i < enemies.length; i++) {
        enemies[i].update();
        enemies[i].draw();
        if (enemies[i].health <= 0) {
            enemies.splice(i, 1);
            i--;
        }
    }

    // Update and draw projectiles
    for (let i = 0; i < projectiles.length; i++) {
        if (projectiles[i].update()) {
            projectiles.splice(i, 1);
            i--;
        } else {
            projectiles[i].draw();
        }
    }

    requestAnimationFrame(gameLoop);
}

// Initial setup
generatePath();
enemies.push(new Enemy(path[0].x, path[0].y)); // Spawn initial enemy

gameLoop();"}
